// Contract: exactly one item {method, params?, caller_workflow?, caller_execution_id?, max_attempts?}.
// Callers use Execute Workflow with mode "each".
const items = $input.all();
if (items.length !== 1) throw new Error(`lib b24_call expects 1 item, got ${items.length}`);
const i = items[0].json;
if (!i.method || !/^[a-z0-9_.]+$/i.test(i.method)) throw new Error(`invalid Bitrix24 method: ${i.method}`);
return [{ json: {
  method: i.method,
  params: i.params ?? {},
  caller_workflow: i.caller_workflow ?? null,
  caller_execution_id: i.caller_execution_id ?? null,
  max_attempts: Math.min(Number(i.max_attempts ?? 5), 8),
  attempt: 1,
}}];

const s = $json;
return [{ json: { method: s.method, params: s.params, caller_workflow: s.caller_workflow, caller_execution_id: s.caller_execution_id,
                  max_attempts: s.max_attempts, attempt: s.attempt + 1 } }];

// Bitrix24 may report errors with HTTP 200, so the body is always inspected.
const s = $('Stamp').first().json;
const status = Number($json.statusCode ?? 0);
let body = $json.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch { body = { error: 'NON_JSON_RESPONSE', error_description: body.slice(0, 300) }; } }
body = body ?? {};
const RETRYABLE_CODES = ['QUERY_LIMIT_EXCEEDED', 'OPERATION_TIME_LIMIT', 'INTERNAL_SERVER_ERROR'];
const errorCode = body.error ? String(body.error) : (status >= 400 ? `HTTP_${status}` : null);
const ok = !errorCode;
const retryable = !ok && (RETRYABLE_CODES.includes(errorCode) || [429, 500, 502, 503, 504].includes(status));
const t = body.time ?? {};
// Exponential backoff with jitter; OPERATION_TIME_LIMIT waits until the oldest minute bucket resets.
let backoff = Math.min(30000, 1000 * 2 ** (s.attempt - 1)) + Math.floor(Math.random() * 250);
if (errorCode === 'OPERATION_TIME_LIMIT' && t.operating_reset_at) {
  backoff = Math.max(backoff, Math.min(60000, t.operating_reset_at * 1000 - Date.now()));
}
return [{ json: {
  ...s,
  ok, retryable, http_status: status,
  error_code: errorCode,
  error_description: ok ? null : String(body.error_description ?? '').slice(0, 1000),
  result: ok ? body.result : null,
  total: body.total ?? null,
  next: body.next ?? null,
  result_error: body.result_error ?? null,
  operating: t.operating ?? null,
  operating_reset_at: t.operating_reset_at ? new Date(t.operating_reset_at * 1000).toISOString() : null,
  duration_ms: Date.now() - s.sent_at,
  backoff_ms: backoff,
  will_retry: retryable && s.attempt < s.max_attempts,
}}];

const s = $json;
return [{ json: {
  ok: s.ok, method: s.method, result: s.result, total: s.total, next: s.next, result_error: s.result_error,
  error_code: s.error_code, error_description: s.error_description, http_status: s.http_status,
  attempts: s.attempt, operating: s.operating,
}}];

// Wait-node wake-up can be a few ms early; never send before the reserved slot.
const s = $json;
while (Date.now() < s.slot_at_ms) { /* spin <= few ms */ }
return [{ json: { ...s, sent_at: Date.now() } }];

const s = { ...JSON.parse($json.state_text), slot_at_ms: Number($json.slot_at_ms),
            base_url: $json.base_url, auth_mode: $json.auth_mode, access_token: $json.access_token };
if (!s.base_url) throw new Error('b24_auth is not configured: run scripts/seed_config.sh');
return [{ json: s }];
